# Let me try the full 8-element sequence with start = col for all rows
width = 18
seq = [2, 1, 3, 8, 4, 5, 6, 7]

output = [[0] * width for _ in range(17)]
nonzeros = [(0,0), (1,11), (3,3), (5,13), (9,7), (11,13), (13,4)]

for row, col in nonzeros:
    for i, val in enumerate(seq):
        output[row][(col + i) % width] = val

# Last row unchanged
output[16] = [2, 1, 3, 8, 0, 0, 0, 0, 0, 0, 0, 0, 4, 5, 6, 7]

for i, row in enumerate(output):
    if any(x != 0 for x in row):
        print(f"Row {i}: {' '.join(map(str, row))}")

print(f"\nFull output:")
for i, row in enumerate(output):
    print(f"Row {i}: {' '.join(map(str, row))}")

